findings.codeql_raw_query:
/**
 * @name Path traversal in zip file extraction
 * @description Extracting zip files without validating paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for zipfile.ZipFile.extract, zipfile.ZipFile.extractall, zipfile.ZipFile.open
    exists(API::CallNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getACall()
      and
      exists(API::CallNode methodCall |
        (
          // extract method - first argument is member name
          methodCall = call.getReturn().getMember("extract").getACall()
          and sink = methodCall.getArg(0)
        )
        or
        (
          // extractall method - first argument is path
          methodCall = call.getReturn().getMember("extractall").getACall()
          and sink = methodCall.getArg(0)
        )
        or
        (
          // open method - first argument is name
          methodCall = call.getReturn().getMember("open").getACall()
          and sink = methodCall.getArg(0)
        )
      )
    )
    or
    // Also check for shutil.unpack_archive
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember("unpack_archive").getACall()
      and
      sink = call.getArg(0)  // filename argument
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"
